import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiUpload,
  FiUsers,
  FiX,
  FiImage,
  FiMail,
  FiPhone,
} from 'react-icons/fi';

import { toast } from 'react-toastify';

import api from '../../services/api';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const API_BASE_URL =
  process.env.REACT_APP_API_URL ||
  'http://127.0.0.1:8000';


const initialForm = {
  name_en: '',
  name_km: '',

  position_en: '',
  position_km: '',

  bio_en: '',
  bio_km: '',

  email: '',
  phone: '',

  facebook_url: '',
  linkedin_url: '',

  is_active: true,
  order: 0,
};


const AdminLeadership = () => {
  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km';


  // ==========================================
  // TRANSLATION WITH FALLBACK
  // ==========================================

  const tr = (
    key,
    english,
    khmer
  ) => {
    const translated =
      t(key);

    if (
      translated &&
      translated !== key
    ) {
      return translated;
    }

    return isKhmer
      ? khmer
      : english;
  };


  // ==========================================
  // CURRENT LANGUAGE FIELDS
  // ==========================================

  const nameField =
    isKhmer
      ? 'name_km'
      : 'name_en';


  const positionField =
    isKhmer
      ? 'position_km'
      : 'position_en';


  const bioField =
    isKhmer
      ? 'bio_km'
      : 'bio_en';


  // ==========================================
  // STATE
  // ==========================================

  const [
    members,
    setMembers,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    saving,
    setSaving,
  ] = useState(false);


  const [
    showModal,
    setShowModal,
  ] = useState(false);


  const [
    editingMember,
    setEditingMember,
  ] = useState(null);


  const [
    imageFile,
    setImageFile,
  ] = useState(null);


  const [
    imagePreview,
    setImagePreview,
  ] = useState(null);


  const [
    imageRemoved,
    setImageRemoved,
  ] = useState(false);


  const [
    formData,
    setFormData,
  ] = useState({
    ...initialForm,
  });


  const fileInputRef =
    useRef(null);


  // ==========================================
  // IMAGE URL
  // ==========================================

  const getImageUrl = (
    image
  ) => {
    if (!image) {
      return null;
    }

    if (
      image.startsWith('http://') ||
      image.startsWith('https://')
    ) {
      return image;
    }

    if (
      image.startsWith('/')
    ) {
      return `${API_BASE_URL}${image}`;
    }

    return `${API_BASE_URL}/${image}`;
  };


  // ==========================================
  // DISPLAY NAME
  // ==========================================

  const getMemberName = (
    member
  ) => {
    if (!member) {
      return '-';
    }

    if (isKhmer) {
      return (
        member.name_km ||
        member.name_en ||
        '-'
      );
    }

    return (
      member.name_en ||
      member.name_km ||
      '-'
    );
  };


  // ==========================================
  // DISPLAY POSITION
  // ==========================================

  const getMemberPosition = (
    member
  ) => {
    if (!member) {
      return '-';
    }

    if (isKhmer) {
      return (
        member.position_km ||
        member.position_en ||
        '-'
      );
    }

    return (
      member.position_en ||
      member.position_km ||
      '-'
    );
  };


  // ==========================================
  // DISPLAY BIO
  // ==========================================

  const getMemberBio = (
    member
  ) => {
    if (!member) {
      return '';
    }

    if (isKhmer) {
      return (
        member.bio_km ||
        member.bio_en ||
        ''
      );
    }

    return (
      member.bio_en ||
      member.bio_km ||
      ''
    );
  };


  // ==========================================
  // FETCH
  // ==========================================

  const fetchMembers =
    async () => {
      try {
        setLoading(true);

        const response =
          await api.get(
            '/api/leadership/'
          );

        const data =
          response.data;

        if (
          Array.isArray(data)
        ) {
          setMembers(data);
        } else if (
          Array.isArray(
            data?.items
          )
        ) {
          setMembers(
            data.items
          );
        } else {
          setMembers([]);
        }
      } catch (error) {
        console.error(
          'Leadership load error:',
          error
        );

        toast.error(
          error?.response?.data
            ?.detail ||
            tr(
              'leadership.loadFailed',
              'Failed to load leadership team.',
              'មិនអាចផ្ទុកក្រុមថ្នាក់ដឹកនាំបានទេ។'
            )
        );
      } finally {
        setLoading(false);
      }
    };


  useEffect(() => {
    fetchMembers();
  }, []);


  // ==========================================
  // CLEAN IMAGE PREVIEW
  // ==========================================

  useEffect(() => {
    return () => {
      if (
        imagePreview &&
        imagePreview.startsWith(
          'blob:'
        )
      ) {
        URL.revokeObjectURL(
          imagePreview
        );
      }
    };
  }, [imagePreview]);


  // ==========================================
  // RESET
  // ==========================================

  const resetForm = () => {
    setFormData({
      ...initialForm,
    });

    setEditingMember(null);

    setImageFile(null);

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {
      URL.revokeObjectURL(
        imagePreview
      );
    }

    setImagePreview(null);

    setImageRemoved(false);

    if (
      fileInputRef.current
    ) {
      fileInputRef.current.value =
        '';
    }

    setSaving(false);
  };


  // ==========================================
  // ADD
  // ==========================================

  const handleAdd = () => {
    resetForm();

    setShowModal(true);
  };


  // ==========================================
  // CLOSE
  // ==========================================

  const handleCloseModal = () => {
    if (saving) {
      return;
    }

    setShowModal(false);

    resetForm();
  };


  // ==========================================
  // EDIT
  // ==========================================

  const handleEdit = (
    member
  ) => {
    setEditingMember(
      member
    );

    setFormData({
      name_en:
        member.name_en ||
        '',

      name_km:
        member.name_km ||
        '',

      position_en:
        member.position_en ||
        '',

      position_km:
        member.position_km ||
        '',

      bio_en:
        member.bio_en ||
        '',

      bio_km:
        member.bio_km ||
        '',

      email:
        member.email ||
        '',

      phone:
        member.phone ||
        '',

      facebook_url:
        member.facebook_url ||
        '',

      linkedin_url:
        member.linkedin_url ||
        '',

      is_active:
        member.is_active ??
        true,

      order:
        member.order ??
        0,
    });

    setImageFile(null);

    setImageRemoved(false);

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {
      URL.revokeObjectURL(
        imagePreview
      );
    }

    setImagePreview(
      member.image
        ? getImageUrl(
            member.image
          )
        : null
    );

    if (
      fileInputRef.current
    ) {
      fileInputRef.current.value =
        '';
    }

    setShowModal(true);
  };


  // ==========================================
  // INPUT CHANGE
  // ==========================================

  const handleChange = (
    event
  ) => {
    const {
      name,
      value,
      type,
      checked,
    } = event.target;

    setFormData(
      (previous) => ({
        ...previous,

        [name]:
          type === 'checkbox'
            ? checked
            : value,
      })
    );
  };


  // ==========================================
  // IMAGE CHANGE
  // ==========================================

  const handleImageChange = (
    event
  ) => {
    const file =
      event.target.files?.[0];

    if (!file) {
      return;
    }

    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];

    if (
      !allowedTypes.includes(
        file.type
      )
    ) {
      toast.error(
        tr(
          'leadership.invalidImage',
          'Please select a JPG, JPEG, PNG or WEBP image.',
          'សូមជ្រើសរើសរូបភាព JPG, JPEG, PNG ឬ WEBP។'
        )
      );

      event.target.value =
        '';

      return;
    }

    const maxSize =
      5 * 1024 * 1024;

    if (
      file.size > maxSize
    ) {
      toast.error(
        tr(
          'leadership.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );

      event.target.value =
        '';

      return;
    }

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {
      URL.revokeObjectURL(
        imagePreview
      );
    }

    setImageFile(file);

    setImageRemoved(false);

    setImagePreview(
      URL.createObjectURL(
        file
      )
    );
  };


  // ==========================================
  // REMOVE IMAGE
  // ==========================================

  const handleRemoveImage = () => {
    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {
      URL.revokeObjectURL(
        imagePreview
      );
    }

    setImageFile(null);

    setImagePreview(null);

    setImageRemoved(true);

    if (
      fileInputRef.current
    ) {
      fileInputRef.current.value =
        '';
    }
  };


  // ==========================================
  // SUBMIT
  // ==========================================

  const handleSubmit =
    async (event) => {
      event.preventDefault();

      const currentName =
        String(
          formData[
            nameField
          ] || ''
        ).trim();

      const currentPosition =
        String(
          formData[
            positionField
          ] || ''
        ).trim();


      if (!currentName) {
        toast.error(
          tr(
            'leadership.nameRequired',
            'Name is required.',
            'សូមបញ្ចូលឈ្មោះ។'
          )
        );

        return;
      }


      if (!currentPosition) {
        toast.error(
          tr(
            'leadership.positionRequired',
            'Position is required.',
            'សូមបញ្ចូលតួនាទី។'
          )
        );

        return;
      }


      try {
        setSaving(true);

        const data =
          new FormData();


        // ====================================
        // CREATE
        // Backend requires both languages.
        // Current language is used as default
        // if other language is still empty.
        // ====================================

        if (!editingMember) {
          const nameEn =
            formData.name_en.trim() ||
            currentName;

          const nameKm =
            formData.name_km.trim() ||
            currentName;

          const positionEn =
            formData.position_en.trim() ||
            currentPosition;

          const positionKm =
            formData.position_km.trim() ||
            currentPosition;

          const bioEn =
            formData.bio_en.trim() ||
            formData[
              bioField
            ].trim();

          const bioKm =
            formData.bio_km.trim() ||
            formData[
              bioField
            ].trim();


          data.append(
            'name_en',
            nameEn
          );

          data.append(
            'name_km',
            nameKm
          );

          data.append(
            'position_en',
            positionEn
          );

          data.append(
            'position_km',
            positionKm
          );

          data.append(
            'bio_en',
            bioEn
          );

          data.append(
            'bio_km',
            bioKm
          );
        }


        // ====================================
        // EDIT
        // Only update selected language
        // ====================================

        if (editingMember) {
          data.append(
            nameField,
            currentName
          );

          data.append(
            positionField,
            currentPosition
          );

          data.append(
            bioField,
            String(
              formData[
                bioField
              ] || ''
            ).trim()
          );
        }


        // ====================================
        // COMMON FIELDS
        // ====================================

        data.append(
          'email',
          formData.email.trim()
        );

        data.append(
          'phone',
          formData.phone.trim()
        );

        data.append(
          'facebook_url',
          formData.facebook_url.trim()
        );

        data.append(
          'linkedin_url',
          formData.linkedin_url.trim()
        );

        data.append(
          'is_active',
          String(
            formData.is_active
          )
        );

        data.append(
          'order',
          String(
            Number(
              formData.order
            ) || 0
          )
        );


        if (imageFile) {
          data.append(
            'image',
            imageFile
          );
        }


        if (
          editingMember &&
          imageRemoved &&
          !imageFile
        ) {
          data.append(
            'remove_image',
            'true'
          );
        }


        // ====================================
        // UPDATE
        // ====================================

        if (editingMember) {
          await api.put(
            `/api/leadership/${editingMember.id}`,
            data
          );

          toast.success(
            tr(
              'leadership.updatedSuccess',
              'Leadership member updated successfully.',
              'បានកែប្រែសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
            )
          );
        } else {
          // ==================================
          // CREATE
          // ==================================

          await api.post(
            '/api/leadership/',
            data
          );

          toast.success(
            tr(
              'leadership.createdSuccess',
              'Leadership member added successfully.',
              'បានបន្ថែមសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
            )
          );
        }


        setShowModal(false);

        resetForm();

        await fetchMembers();
      } catch (error) {
        console.error(
          'Leadership submit error:',
          error
        );

        const detail =
          error?.response?.data
            ?.detail ||
          error?.response?.data
            ?.message;


        if (
          Array.isArray(detail)
        ) {
          toast.error(
            detail
              .map(
                (item) =>
                  item?.msg ||
                  'Validation error'
              )
              .join(', ')
          );
        } else {
          toast.error(
            detail ||
              tr(
                'common.operationFailed',
                'Failed to save leadership member.',
                'មិនអាចរក្សាទុកសមាជិកថ្នាក់ដឹកនាំបានទេ។'
              )
          );
        }
      } finally {
        setSaving(false);
      }
    };


  // ==========================================
  // DELETE
  // ==========================================

  const handleDelete =
    async (member) => {
      const confirmed =
        window.confirm(
          `${tr(
            'leadership.deleteConfirm',
            'Are you sure you want to delete this leadership member?',
            'តើអ្នកប្រាកដថាចង់លុបសមាជិកថ្នាក់ដឹកនាំនេះមែនទេ?'
          )}\n\n${getMemberName(
            member
          )}`
        );

      if (!confirmed) {
        return;
      }

      try {
        await api.delete(
          `/api/leadership/${member.id}`
        );

        toast.success(
          tr(
            'leadership.deletedSuccess',
            'Leadership member deleted successfully.',
            'បានលុបសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
          )
        );

        await fetchMembers();
      } catch (error) {
        console.error(
          'Leadership delete error:',
          error
        );

        toast.error(
          error?.response?.data
            ?.detail ||
            tr(
              'leadership.deleteFailed',
              'Failed to delete leadership member.',
              'មិនអាចលុបសមាជិកថ្នាក់ដឹកនាំបានទេ។'
            )
        );
      }
    };


  // ==========================================
  // LOADING
  // ==========================================

  if (loading) {
    return (
      <div className="min-h-[400px] flex items-center justify-center">

        <div className="text-center">

          <div className="w-12 h-12 mx-auto rounded-full border-4 border-blue-100 border-t-blue-950 animate-spin" />

          <p className="mt-4 text-sm text-blue-400">
            {tr(
              'common.loading',
              'Loading...',
              'កំពុងផ្ទុក...'
            )}
          </p>

        </div>

      </div>
    );
  }


  return (
    <div
      className={
        isKhmer
          ? 'font-khmer'
          : ''
      }
    >

      {/* ======================================
          HEADER
      ====================================== */}

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">

        <div>

          <h1 className="text-2xl font-bold text-blue-950">
            {tr(
              'leadership.title',
              'Leadership Team',
              'ក្រុមថ្នាក់ដឹកនាំ'
            )}
          </h1>

          <p className="mt-1 text-sm text-blue-400">
            {tr(
              'leadership.subtitle',
              'Manage SC Academy leadership members',
              'គ្រប់គ្រងសមាជិកថ្នាក់ដឹកនាំ SC Academy'
            )}
          </p>

        </div>


        <button
          type="button"
          onClick={handleAdd}
          className="inline-flex items-center justify-center gap-2 px-5 py-2.5 bg-red-600 text-white rounded-xl font-semibold hover:bg-red-700 transition"
        >
          <FiPlus size={18} />

          {tr(
            'leadership.addMember',
            'Add Member',
            'បន្ថែមសមាជិក'
          )}
        </button>

      </div>


      {/* ======================================
          SUMMARY
      ====================================== */}

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">

        <div className="bg-white border border-blue-100 rounded-2xl p-5 shadow-sm">

          <div className="flex items-center justify-between">

            <div>

              <p className="text-sm text-blue-400">
                {tr(
                  'leadership.totalMembers',
                  'Total Members',
                  'សមាជិកសរុប'
                )}
              </p>

              <p className="text-3xl font-bold text-blue-950 mt-2">
                {members.length}
              </p>

            </div>

            <div className="w-12 h-12 rounded-xl bg-blue-50 text-blue-950 flex items-center justify-center">
              <FiUsers size={22} />
            </div>

          </div>

        </div>


        <div className="bg-white border border-blue-100 rounded-2xl p-5 shadow-sm">

          <div className="flex items-center justify-between">

            <div>

              <p className="text-sm text-blue-400">
                {tr(
                  'leadership.activeMembers',
                  'Active Members',
                  'សមាជិកសកម្ម'
                )}
              </p>

              <p className="text-3xl font-bold text-blue-950 mt-2">
                {
                  members.filter(
                    (member) =>
                      member.is_active
                  ).length
                }
              </p>

            </div>

            <div className="w-12 h-12 rounded-xl bg-red-50 text-red-600 flex items-center justify-center">
              <FiUsers size={22} />
            </div>

          </div>

        </div>

      </div>


      {/* ======================================
          MEMBERS TABLE
      ====================================== */}

      <div className="bg-white border border-blue-100 rounded-2xl shadow-sm overflow-hidden">

        <div className="overflow-x-auto">

          <table className="w-full">

            <thead className="bg-blue-50 border-b border-blue-100">

              <tr>

                <th className="text-left px-5 py-4 text-xs font-semibold uppercase tracking-wide text-blue-500">
                  {tr(
                    'leadership.member',
                    'Member',
                    'សមាជិក'
                  )}
                </th>

                <th className="text-left px-5 py-4 text-xs font-semibold uppercase tracking-wide text-blue-500">
                  {tr(
                    'leadership.position',
                    'Position',
                    'តួនាទី'
                  )}
                </th>

                <th className="text-left px-5 py-4 text-xs font-semibold uppercase tracking-wide text-blue-500">
                  {tr(
                    'common.status',
                    'Status',
                    'ស្ថានភាព'
                  )}
                </th>

                <th className="text-left px-5 py-4 text-xs font-semibold uppercase tracking-wide text-blue-500">
                  {tr(
                    'common.order',
                    'Order',
                    'លំដាប់'
                  )}
                </th>

                <th className="text-right px-5 py-4 text-xs font-semibold uppercase tracking-wide text-blue-500">
                  {tr(
                    'common.actions',
                    'Actions',
                    'សកម្មភាព'
                  )}
                </th>

              </tr>

            </thead>


            <tbody className="divide-y divide-blue-50">

              {
                members.length === 0 ? (

                  <tr>

                    <td
                      colSpan="5"
                      className="px-5 py-16 text-center"
                    >

                      <FiUsers
                        size={36}
                        className="mx-auto text-blue-200"
                      />

                      <p className="mt-3 text-blue-400">
                        {tr(
                          'common.noData',
                          'No data found',
                          'មិនមានទិន្នន័យ'
                        )}
                      </p>

                    </td>

                  </tr>

                ) : (

                  members.map(
                    (member) => (

                      <tr
                        key={member.id}
                        className="hover:bg-blue-50/40 transition"
                      >

                        {/* MEMBER */}

                        <td className="px-5 py-4">

                          <div className="flex items-center gap-3">

                            <div className="w-14 h-14 rounded-xl overflow-hidden bg-blue-50 border border-blue-100 flex-shrink-0 flex items-center justify-center">

                              {
                                member.image ? (

                                  <img
                                    src={
                                      getImageUrl(
                                        member.image
                                      )
                                    }
                                    alt={
                                      getMemberName(
                                        member
                                      )
                                    }
                                    className="w-full h-full object-cover"
                                  />

                                ) : (

                                  <FiUsers
                                    size={22}
                                    className="text-blue-300"
                                  />

                                )
                              }

                            </div>


                            <div className="min-w-0">

                              <p className="font-semibold text-blue-950">
                                {getMemberName(
                                  member
                                )}
                              </p>

                              {
                                member.email && (

                                  <p className="mt-1 text-xs text-blue-400 flex items-center gap-1.5">
                                    <FiMail />

                                    {member.email}
                                  </p>

                                )
                              }

                            </div>

                          </div>

                        </td>


                        {/* POSITION */}

                        <td className="px-5 py-4">

                          <p className="font-medium text-blue-900">
                            {getMemberPosition(
                              member
                            )}
                          </p>

                          {
                            getMemberBio(
                              member
                            ) && (

                              <p className="mt-1 text-xs text-blue-400 max-w-xs line-clamp-2">
                                {getMemberBio(
                                  member
                                )}
                              </p>

                            )
                          }

                        </td>


                        {/* STATUS */}

                        <td className="px-5 py-4">

                          <span
                            className={`inline-flex items-center px-3 py-1.5 rounded-full text-xs font-semibold ${
                              member.is_active
                                ? 'bg-blue-50 text-blue-700'
                                : 'bg-red-50 text-red-600'
                            }`}
                          >
                            {
                              member.is_active
                                ? tr(
                                    'common.active',
                                    'Active',
                                    'សកម្ម'
                                  )
                                : tr(
                                    'common.inactive',
                                    'Inactive',
                                    'អសកម្ម'
                                  )
                            }
                          </span>

                        </td>


                        {/* ORDER */}

                        <td className="px-5 py-4 text-sm text-blue-500">
                          {member.order ?? 0}
                        </td>


                        {/* ACTION */}

                        <td className="px-5 py-4">

                          <div className="flex items-center justify-end gap-2">

                            <button
                              type="button"
                              onClick={() =>
                                handleEdit(
                                  member
                                )
                              }
                              title={tr(
                                'common.edit',
                                'Edit',
                                'កែប្រែ'
                              )}
                              className="w-9 h-9 rounded-lg bg-blue-50 text-blue-950 flex items-center justify-center hover:bg-blue-950 hover:text-white transition"
                            >
                              <FiEdit2
                                size={16}
                              />
                            </button>


                            <button
                              type="button"
                              onClick={() =>
                                handleDelete(
                                  member
                                )
                              }
                              title={tr(
                                'common.delete',
                                'Delete',
                                'លុប'
                              )}
                              className="w-9 h-9 rounded-lg bg-red-50 text-red-600 flex items-center justify-center hover:bg-red-600 hover:text-white transition"
                            >
                              <FiTrash2
                                size={16}
                              />
                            </button>

                          </div>

                        </td>

                      </tr>

                    )
                  )

                )
              }

            </tbody>

          </table>

        </div>

      </div>


      {/* ======================================
          MODAL
      ====================================== */}

      {
        showModal && (

          <div className="fixed inset-0 z-50 bg-blue-950/50 backdrop-blur-sm flex items-center justify-center p-4">

            <div className="w-full max-w-3xl max-h-[92vh] bg-white rounded-2xl shadow-2xl overflow-hidden flex flex-col">

              {/* MODAL HEADER */}

              <div className="flex items-center justify-between gap-4 px-6 py-5 bg-blue-950 text-white">

                <div>

                  <p className="text-xs text-blue-200 uppercase tracking-wider font-semibold">
                    {tr(
                      'leadership.title',
                      'Leadership Team',
                      'ក្រុមថ្នាក់ដឹកនាំ'
                    )}
                  </p>

                  <h2 className="text-xl font-bold mt-1">
                    {
                      editingMember
                        ? tr(
                            'leadership.editMember',
                            'Edit Member',
                            'កែប្រែសមាជិក'
                          )
                        : tr(
                            'leadership.addMember',
                            'Add Member',
                            'បន្ថែមសមាជិក'
                          )
                    }
                  </h2>

                </div>


                <button
                  type="button"
                  onClick={
                    handleCloseModal
                  }
                  disabled={saving}
                  className="w-10 h-10 rounded-xl bg-white/10 hover:bg-white/20 flex items-center justify-center transition"
                >
                  <FiX size={21} />
                </button>

              </div>


              {/* MODAL BODY */}

              <div className="flex-1 overflow-y-auto">

                <form
                  id="leadership-form"
                  onSubmit={
                    handleSubmit
                  }
                  className="p-6 space-y-6"
                >

                  {/* ==================================
                      IMAGE
                  ================================== */}

                  <div>

                    <label className="block text-sm font-semibold text-blue-950 mb-2">
                      {tr(
                        'leadership.memberPhoto',
                        'Member Photo',
                        'រូបភាពសមាជិក'
                      )}
                    </label>


                    <div className="border-2 border-dashed border-blue-200 rounded-2xl p-5">

                      <div className="flex flex-col sm:flex-row sm:items-center gap-5">

                        <div className="w-28 h-28 rounded-2xl bg-blue-50 border border-blue-100 overflow-hidden flex items-center justify-center flex-shrink-0">

                          {
                            imagePreview ? (

                              <img
                                src={
                                  imagePreview
                                }
                                alt="Preview"
                                className="w-full h-full object-cover"
                              />

                            ) : (

                              <FiImage
                                size={32}
                                className="text-blue-300"
                              />

                            )
                          }

                        </div>


                        <div className="flex-1">

                          <input
                            ref={
                              fileInputRef
                            }
                            id="leadership-image"
                            type="file"
                            accept="image/jpeg,image/jpg,image/png,image/webp"
                            onChange={
                              handleImageChange
                            }
                            className="hidden"
                          />


                          <div className="flex flex-wrap gap-2">

                            <label
                              htmlFor="leadership-image"
                              className="inline-flex items-center gap-2 px-4 py-2.5 bg-blue-950 text-white rounded-xl text-sm font-semibold cursor-pointer hover:bg-blue-900 transition"
                            >
                              <FiUpload />

                              {tr(
                                'leadership.chooseImage',
                                'Choose Image',
                                'ជ្រើសរើសរូបភាព'
                              )}
                            </label>


                            {
                              imagePreview && (

                                <button
                                  type="button"
                                  onClick={
                                    handleRemoveImage
                                  }
                                  className="px-4 py-2.5 bg-red-50 text-red-600 rounded-xl text-sm font-semibold hover:bg-red-600 hover:text-white transition"
                                >
                                  {tr(
                                    'leadership.removePhoto',
                                    'Remove Photo',
                                    'ដករូបភាពចេញ'
                                  )}
                                </button>

                              )
                            }

                          </div>


                          <p className="mt-2 text-xs text-blue-400">
                            {tr(
                              'leadership.imageHelp',
                              'JPG, JPEG, PNG or WEBP. Maximum 5 MB.',
                              'JPG, JPEG, PNG ឬ WEBP។ ទំហំអតិបរមា 5 MB។'
                            )}
                          </p>

                        </div>

                      </div>

                    </div>

                  </div>


                  {/* ==================================
                      NAME
                  ================================== */}

                  <div>

                    <label className="block text-sm font-semibold text-blue-950 mb-2">

                      {tr(
                        'leadership.name',
                        'Name',
                        'ឈ្មោះ'
                      )}

                      <span className="text-red-600 ml-1">
                        *
                      </span>

                    </label>


                    <input
                      type="text"
                      name={nameField}
                      value={
                        formData[
                          nameField
                        ]
                      }
                      onChange={
                        handleChange
                      }
                      placeholder={tr(
                        'leadership.namePlaceholder',
                        'Enter member name',
                        'បញ្ចូលឈ្មោះសមាជិក'
                      )}
                      className="w-full h-12 px-4 border border-blue-200 rounded-xl text-blue-950 placeholder:text-blue-300 focus:outline-none focus:ring-2 focus:ring-blue-950/10 focus:border-blue-950 transition"
                    />

                  </div>


                  {/* ==================================
                      POSITION
                  ================================== */}

                  <div>

                    <label className="block text-sm font-semibold text-blue-950 mb-2">

                      {tr(
                        'leadership.position',
                        'Position',
                        'តួនាទី'
                      )}

                      <span className="text-red-600 ml-1">
                        *
                      </span>

                    </label>


                    <input
                      type="text"
                      name={
                        positionField
                      }
                      value={
                        formData[
                          positionField
                        ]
                      }
                      onChange={
                        handleChange
                      }
                      placeholder={tr(
                        'leadership.positionPlaceholder',
                        'e.g. School Principal',
                        'ឧ. នាយកសាលា'
                      )}
                      className="w-full h-12 px-4 border border-blue-200 rounded-xl text-blue-950 placeholder:text-blue-300 focus:outline-none focus:ring-2 focus:ring-blue-950/10 focus:border-blue-950 transition"
                    />

                  </div>


                  {/* ==================================
                      BIOGRAPHY
                  ================================== */}

                  <div>

                    <label className="block text-sm font-semibold text-blue-950 mb-2">
                      {tr(
                        'leadership.biography',
                        'Biography',
                        'ជីវប្រវត្តិ'
                      )}
                    </label>


                    <textarea
                      name={
                        bioField
                      }
                      value={
                        formData[
                          bioField
                        ]
                      }
                      onChange={
                        handleChange
                      }
                      rows={5}
                      placeholder={tr(
                        'leadership.biographyPlaceholder',
                        'Enter biography',
                        'បញ្ចូលជីវប្រវត្តិ'
                      )}
                      className="w-full px-4 py-3 border border-blue-200 rounded-xl text-blue-950 placeholder:text-blue-300 resize-y focus:outline-none focus:ring-2 focus:ring-blue-950/10 focus:border-blue-950 transition"
                    />

                  </div>


                  {/* ==================================
                      CONTACT
                  ================================== */}

                  <div className="border-t border-blue-100 pt-6">

                    <h3 className="font-semibold text-blue-950 mb-4">
                      {tr(
                        'leadership.contactInformation',
                        'Contact Information',
                        'ព័ត៌មានទំនាក់ទំនង'
                      )}
                    </h3>


                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

                      {/* EMAIL */}

                      <div>

                        <label className="block text-sm font-semibold text-blue-950 mb-2">
                          {tr(
                            'common.email',
                            'Email',
                            'អ៊ីមែល'
                          )}
                        </label>


                        <div className="relative">

                          <FiMail className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-300" />

                          <input
                            type="email"
                            name="email"
                            value={
                              formData.email
                            }
                            onChange={
                              handleChange
                            }
                            placeholder="example@email.com"
                            className="w-full h-12 pl-11 pr-4 border border-blue-200 rounded-xl focus:outline-none focus:border-blue-950"
                          />

                        </div>

                      </div>


                      {/* PHONE */}

                      <div>

                        <label className="block text-sm font-semibold text-blue-950 mb-2">
                          {tr(
                            'common.phone',
                            'Phone',
                            'លេខទូរស័ព្ទ'
                          )}
                        </label>


                        <div className="relative">

                          <FiPhone className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-300" />

                          <input
                            type="text"
                            name="phone"
                            value={
                              formData.phone
                            }
                            onChange={
                              handleChange
                            }
                            placeholder="012 345 678"
                            className="w-full h-12 pl-11 pr-4 border border-blue-200 rounded-xl focus:outline-none focus:border-blue-950"
                          />

                        </div>

                      </div>


                      {/* FACEBOOK */}

                      <div>

                        <label className="block text-sm font-semibold text-blue-950 mb-2">
                          Facebook URL
                        </label>

                        <input
                          type="url"
                          name="facebook_url"
                          value={
                            formData.facebook_url
                          }
                          onChange={
                            handleChange
                          }
                          placeholder="Facebook URL"
                          className="w-full h-12 px-4 border border-blue-200 rounded-xl focus:outline-none focus:border-blue-950"
                        />

                      </div>


                      {/* LINKEDIN */}

                      <div>

                        <label className="block text-sm font-semibold text-blue-950 mb-2">
                          LinkedIn URL
                        </label>

                        <input
                          type="url"
                          name="linkedin_url"
                          value={
                            formData.linkedin_url
                          }
                          onChange={
                            handleChange
                          }
                          placeholder="LinkedIn URL"
                          className="w-full h-12 px-4 border border-blue-200 rounded-xl focus:outline-none focus:border-blue-950"
                        />

                      </div>

                    </div>

                  </div>


                  {/* ==================================
                      GENERAL
                  ================================== */}

                  <div className="border-t border-blue-100 pt-6">

                    <h3 className="font-semibold text-blue-950 mb-4">
                      {tr(
                        'common.generalInformation',
                        'General Information',
                        'ព័ត៌មានទូទៅ'
                      )}
                    </h3>


                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

                      {/* ORDER */}

                      <div>

                        <label className="block text-sm font-semibold text-blue-950 mb-2">
                          {tr(
                            'leadership.displayOrder',
                            'Display Order',
                            'លំដាប់បង្ហាញ'
                          )}
                        </label>

                        <input
                          type="number"
                          name="order"
                          min="0"
                          value={
                            formData.order
                          }
                          onChange={
                            handleChange
                          }
                          className="w-full h-12 px-4 border border-blue-200 rounded-xl focus:outline-none focus:border-blue-950"
                        />

                      </div>


                      {/* STATUS */}

                      <div>

                        <label className="block text-sm font-semibold text-blue-950 mb-2">
                          {tr(
                            'common.status',
                            'Status',
                            'ស្ថានភាព'
                          )}
                        </label>


                        <button
                          type="button"
                          onClick={() =>
                            setFormData(
                              (
                                previous
                              ) => ({
                                ...previous,

                                is_active:
                                  !previous.is_active,
                              })
                            )
                          }
                          className={`w-full h-12 px-4 rounded-xl border flex items-center justify-between transition ${
                            formData.is_active
                              ? 'bg-blue-50 border-blue-200'
                              : 'bg-red-50 border-red-200'
                          }`}
                        >

                          <span
                            className={`text-sm font-semibold ${
                              formData.is_active
                                ? 'text-blue-700'
                                : 'text-red-600'
                            }`}
                          >
                            {
                              formData.is_active
                                ? tr(
                                    'common.active',
                                    'Active',
                                    'សកម្ម'
                                  )
                                : tr(
                                    'common.inactive',
                                    'Inactive',
                                    'អសកម្ម'
                                  )
                            }
                          </span>


                          <span
                            className={`relative w-11 h-6 rounded-full transition ${
                              formData.is_active
                                ? 'bg-blue-950'
                                : 'bg-red-300'
                            }`}
                          >

                            <span
                              className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow transition-all ${
                                formData.is_active
                                  ? 'left-6'
                                  : 'left-1'
                              }`}
                            />

                          </span>

                        </button>

                      </div>

                    </div>

                  </div>

                </form>

              </div>


              {/* ==================================
                  FOOTER
              ================================== */}

              <div className="px-6 py-4 border-t border-blue-100 bg-blue-50 flex flex-col-reverse sm:flex-row sm:justify-end gap-3">

                <button
                  type="button"
                  onClick={
                    handleCloseModal
                  }
                  disabled={saving}
                  className="px-5 py-2.5 bg-white border border-blue-200 text-blue-700 rounded-xl font-semibold hover:bg-blue-50 disabled:opacity-50 transition"
                >
                  {tr(
                    'common.cancel',
                    'Cancel',
                    'បោះបង់'
                  )}
                </button>


                <button
                  type="submit"
                  form="leadership-form"
                  disabled={saving}
                  className="inline-flex items-center justify-center gap-2 min-w-[140px] px-5 py-2.5 bg-red-600 text-white rounded-xl font-semibold hover:bg-red-700 disabled:opacity-60 transition"
                >

                  {
                    saving ? (

                      <>

                        <span className="w-4 h-4 rounded-full border-2 border-white/40 border-t-white animate-spin" />

                        {tr(
                          'common.saving',
                          'Saving...',
                          'កំពុងរក្សាទុក...'
                        )}

                      </>

                    ) : editingMember ? (

                      <>

                        <FiEdit2 />

                        {tr(
                          'common.update',
                          'Update',
                          'កែប្រែ'
                        )}

                      </>

                    ) : (

                      <>

                        <FiPlus />

                        {tr(
                          'common.create',
                          'Create',
                          'បង្កើត'
                        )}

                      </>

                    )
                  }

                </button>

              </div>

            </div>

          </div>

        )
      }

    </div>
  );
};


export default AdminLeadership;
